"""A tiny to-do list, kept in tasks.txt with one task per line."""
import sys
from pathlib import Path

TASKS = Path("tasks.txt")


def load():
    if not TASKS.exists():
        return []
    return TASKS.read_text().splitlines()


def save(tasks):
    TASKS.write_text("".join(task + "\n" for task in tasks))


def main(args):
    tasks = load()
    if not args:
        for number, task in enumerate(tasks, 1):
            print(f"{number}. {task}")
    elif args[0] == "add":
        tasks.append(" ".join(args[1:]))
        save(tasks)
    elif args[0] == "done":
        number = int(args[1])
        tasks.pop(number)
        save(tasks)
    else:
        print("usage: python todo.py [add TEXT | done NUMBER]")


if __name__ == "__main__":
    main(sys.argv[1:])

